//! New finite-clock/body subframe study only; do not rerun full R439 resources.
use super::{native_appearance_inspection as a,native_appearance_clock_study as clock,sprite};
use std::{fs,path::{Path,PathBuf},collections::BTreeMap};
use sha2::{Digest,Sha256};use serde_json::{Value,json};
fn sha(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}
struct Fixed{root:PathBuf,pins:BTreeMap<String,Value>}
impl Fixed{fn new()->Self{let project=Path::new(env!("CARGO_MANIFEST_DIR"));let p:Value=serde_json::from_slice(&fs::read(project.join("logs/continuation-20261003/r439-appearance-snapshot.json")).unwrap()).unwrap();let root=PathBuf::from(p["candidate"]["root"].as_str().unwrap());let bytes=fs::read(root.join("manifest.json")).unwrap();assert_eq!(sha(&bytes),p["candidate"]["manifest_sha256"].as_str().unwrap().to_ascii_lowercase());let m:Value=serde_json::from_slice(&bytes).unwrap();let pins=m["files"].as_array().unwrap().iter().map(|v|(v["path"].as_str().unwrap().into(),v.clone())).collect();Self{root,pins}}fn bytes(&self,name:&str)->Vec<u8>{assert!(!name.contains("..")&&!Path::new(name).is_absolute());let p=&self.pins[name];let bytes=fs::read(self.root.join(name)).unwrap();assert_eq!(bytes.len()as u64,p["bytes"].as_u64().unwrap());assert_eq!(sha(&bytes),p["sha256"].as_str().unwrap().to_ascii_lowercase());bytes}}
fn inputs(f:&Fixed)->(a::Dependencies,Vec<a::Binding>){(a::nad(&f.bytes("resources/appearance-dependencies.nad")).unwrap(),a::nab(&f.bytes("evidence/appearance-bindings.nab")).unwrap())}
fn ordinary(anchor:u32)->clock::OrdinaryInputs{clock::OrdinaryInputs{ordinary_branch_reached:Some(true),player_global:Some(20000),queue_after_pop:Some(0),modifier_1c:Some(0),modifier_21:Some(0),action21_counter:Some(0),catalog_scaling_disabled:Some(true),frozen_external_state:Some(true),sampled_clock_ms:Some(anchor)}}
#[test]fn original_ordinary_first_advance_zero_tick_is_not_a_visible_clock(){
 let f=Fixed::new();let(d,owners)=inputs(&f);let mut rows=Vec::new();
 for owner in &owners{for heading in 0..8{
 let transition=clock::OrdinaryFirstAdvance::new(true,&d,owner,owner,owner.observed,heading,ordinary(1000)).unwrap();
 let plan=a::plan(true,&d,owner,owner,owner.observed,a::Kind::Attack,heading,128).unwrap();let view=transition.first(owner,owner.observed).unwrap();
 assert_eq!(view.frame,1);assert_eq!(view.selected_catalog,plan.frames[1].0);assert_eq!(view.selected_member,plan.frames[1].1);assert_eq!(view.initial_catalog,plan.frames[0].0);
 let expected=match view.action{1=>125,51|47=>166,_=>panic!("unexpected action")};
 assert_eq!(view.returned_duration_ms,expected);assert_eq!(view.next_delay_ms,expected+2);assert_eq!(view.next_due_ms,1000+expected+2);
 assert!(!view.frame0_visible_residency_qualified&&!view.events_dispatched&&!view.renderer_ready);
 rows.push(json!({"source":owner.source,"object":owner.object,"epoch_hex":format!("{:016x}",owner.epoch),"revision":owner.revision,"heading":heading,"action":view.action,"initial_frame":0,"initial_ticks":view.initial_catalog.ticks,"initial_events_hex":view.initial_catalog.events.iter().map(|b|format!("{b:02x}")).collect::<String>(),"selected_frame":1,"selected_ticks":view.selected_catalog.ticks,"member":view.selected_member.name,"subframe":view.selected_catalog.subframe,"returned_ms":view.returned_duration_ms,"next_delay_ms":view.next_delay_ms,"conditional_next_due_ms":view.next_due_ms,"visible_frame0_residency_qualified":false}));
 transition.retire();assert!(transition.first(owner,owner.observed).is_err());
 }}
 let owner=&owners[0];assert!(clock::OrdinaryFirstAdvance::new(false,&d,owner,owner,owner.observed,0,ordinary(1000)).is_err());
 for selector in 0..8{let mut i=ordinary(1000);match selector{0=>i.ordinary_branch_reached=None,1=>i.player_global=Some(u32::try_from(owner.object).unwrap()),2=>i.queue_after_pop=Some(1),3=>i.modifier_1c=Some(1),4=>i.modifier_21=None,5=>i.catalog_scaling_disabled=None,6=>i.frozen_external_state=Some(false),_=>i.sampled_clock_ms=None};assert!(clock::OrdinaryFirstAdvance::new(true,&d,owner,owner,owner.observed,0,i).is_err());}
 let t=clock::OrdinaryFirstAdvance::new(true,&d,owner,owner,owner.observed,0,ordinary(u32::MAX)).unwrap();assert!(t.first(owner,owner.observed).is_err());
 let t=clock::OrdinaryFirstAdvance::new(true,&d,owner,owner,owner.observed,0,ordinary(1000)).unwrap();let mut other=owner.clone();other.epoch+=1;assert!(t.first(&other,owner.observed).is_err());
 // A later zero tick is not skipped or promoted to a positive duration.
 let mut zero=d.clone();zero.rows.get_mut(&0).unwrap().actions.get_mut(&51).unwrap().frames[1].ticks=0;
 let t=clock::OrdinaryFirstAdvance::new(true,&zero,owner,owner,owner.observed,0,ordinary(1000)).unwrap();assert!(t.first(owner,owner.observed).is_err());
 fs::write(Path::new(env!("CARGO_MANIFEST_DIR")).join("logs/continuation-20261003/r444-first-advance-details.json"),serde_json::to_vec_pretty(&json!({"state":"CONDITIONAL_ORDINARY_FIRST_ADVANCE_ONLY","rows":rows,"initial_zero_tick_cases":24,"initial_positive_tick_cases":8,"actual_runtime_inputs_observed":false,"generic_zero_tick_skip":false,"original_BIN_executed":false,"events_dispatched":false,"frame0_visible_residency_qualified":false,"renderer_LOADED":false,"GUI":0})).unwrap()).unwrap();
}
#[test]fn exact_integer_clock_full_binding_retirement_and_no_loop_grant(){let f=Fixed::new();let(d,b)=inputs(&f);let mut checks=0;let mut rows=Vec::new();let mut unsupported=Vec::new();for owner in &b{for kind in [a::Kind::Walk,a::Kind::Attack]{for heading in 0..8{let plan=a::plan(true,&d,owner,owner,owner.observed,kind,heading,128).unwrap();if plan.frames.iter().any(|(f,_)|f.ticks==0){assert!(clock::Study::new(true,&d,owner,owner,owner.observed,kind,heading,128).is_err());unsupported.push(json!({"source":owner.source,"object":owner.object,"revision":owner.revision,"action":plan.action,"heading":heading,"zero_tick_frames":plan.frames.iter().enumerate().filter(|(_, (f,_))|f.ticks==0).map(|(i,_)|i).collect::<Vec<_>>(),"qualified":false,"reason":"original zero-tick entry/advance timer semantics not admitted"}));continue;}let study=clock::Study::new(true,&d,owner,owner,owner.observed,kind,heading,128).unwrap();let mut start=0;for(i,((catalog,member),duration))in plan.frames.iter().zip(study.duration_ms()).enumerate(){assert_eq!(*duration,u32::from(catalog.ticks)*1000/u32::from(plan.fps));for t in [start,start+u64::from(*duration)-1]{let sample=study.sample(owner,owner.observed,t).unwrap();let v=sample.view(&study,owner,owner.observed).unwrap();assert_eq!(v.frame,i);assert_eq!(v.member.name,member.name);assert_eq!(v.catalog.subframe,catalog.subframe);assert_eq!(v.catalog.events,catalog.events);assert_eq!(v.start_ms,start);assert_eq!(v.end_ms,start+u64::from(*duration));assert_eq!(v.heading,heading);assert!(!v.renderer_ready&&!v.runtime_qualified&&v.game_wire_profile==0);checks+=1;}start+=u64::from(*duration);}assert_eq!(start,study.total_ms());assert!(study.sample(owner,owner.observed,start).is_err());assert!(study.sample(owner,owner.observed,u64::MAX).is_err());rows.push(json!({"source":owner.source,"object":owner.object,"epoch_hex":format!("{:016x}",owner.epoch),"revision":owner.revision,"action":plan.action,"heading":heading,"fps":plan.fps,"durations_ms":study.duration_ms(),"total_ms":study.total_ms(),"natural_loop_qualified":false}));}}}let owner=&b[0];assert!(clock::Study::new(false,&d,owner,owner,owner.observed,a::Kind::Walk,0,128).is_err());let study=clock::Study::new(true,&d,owner,owner,owner.observed,a::Kind::Walk,0,128).unwrap();let sample=study.sample(owner,owner.observed,0).unwrap();let foreign=clock::Study::new(true,&d,owner,owner,owner.observed,a::Kind::Walk,0,128).unwrap();assert!(sample.view(&foreign,owner,owner.observed).is_err());for selector in 0..6{let mut bad=owner.clone();match selector{0=>bad.source=42,1=>bad.epoch+=1,2=>bad.revision+=1,3=>bad.owner[0]^=1,4=>bad.catalog[0]^=1,_=>bad.weapon=0}assert!(study.sample(&bad,owner.observed,0).is_err());}study.retire();assert!(sample.view(&study,owner,owner.observed).is_err());let mut timed=owner.clone();timed.cutoff=timed.observed+1;let timed_study=clock::Study::new(true,&d,&timed,&timed,timed.observed,a::Kind::Walk,0,128).unwrap();assert!(timed_study.sample(&timed,timed.cutoff,0).is_err());let mut bad=d.clone();bad.rows.get_mut(&0).unwrap().actions.get_mut(&50).unwrap().frames[0].ticks=0;assert!(clock::Study::new(true,&bad,owner,owner,owner.observed,a::Kind::Walk,0,128).is_err());fs::write(Path::new(env!("CARGO_MANIFEST_DIR")).join("logs/continuation-20261003/r443-clock-details.json"),serde_json::to_vec_pretty(&json!({"state":"OFFLINE_SINGLE_INTERVAL_CLOCK_BOUNDARIES_AND_FULL_BINDING_GUARDS","plans":rows.len(),"unsupported_zero_tick_plans":unsupported,"boundary_checks":checks,"rows":rows,"R441_R442_live_appearance_authority":false,"raw_events_preserved_not_dispatched":true,"renderer_LOADED":false,"GUI":0})).unwrap()).unwrap();}
#[test]fn actual_SPR_walk_attack_full_cycle_CPU_body_samples(){let f=Fixed::new();let(d,bindings)=inputs(&f);let owners=[&bindings[0],&bindings[1],&bindings[3]];let out=Path::new(env!("CARGO_MANIFEST_DIR")).join("target/r443-appearance-clock-cpu");fs::create_dir_all(&out).unwrap();let mut cache=BTreeMap::new();let mut pins=BTreeMap::new();let mut outputs=Vec::new();for(kind,label)in [(a::Kind::Walk,"walk"),(a::Kind::Attack,"attack")]{let selected=owners.iter().copied().filter(|b|a::plan(true,&d,b,b,b.observed,kind,0,128).unwrap().frames.iter().all(|(f,_)|f.ticks>0)).collect::<Vec<_>>();let plans=selected.iter().map(|b|a::plan(true,&d,b,b,b.observed,kind,0,128).unwrap()).collect::<Vec<_>>();let columns=plans.iter().map(|p|p.frames.len()).max().unwrap();let cell=180usize;let width=columns*cell;let height=selected.len()*cell;let mut rgba=vec![0u8;width*height*4];for y in 0..height{for x in 0..width{rgba[(y*width+x)*4..(y*width+x+1)*4].copy_from_slice(if(x/10+y/10)%2==0{&[32,35,40,255]}else{&[40,43,48,255]});}}let mut cells=Vec::new();for(row,owner)in selected.iter().enumerate(){let study=clock::Study::new(true,&d,owner,owner,owner.observed,kind,0,128).unwrap();let mut start=0;for column in 0..study.duration_ms().len(){let sample=study.sample(owner,owner.observed,start).unwrap();let v=sample.view(&study,owner,owner.observed).unwrap();if !cache.contains_key(&v.member.name){let b=f.bytes(&format!("resources/{}",v.member.name));assert_eq!(b.len()as u64,v.member.bytes);assert_eq!(<[u8;32]>::from(Sha256::digest(&b)),v.member.sha256);let raw=b.strip_prefix(b"SPR_0").unwrap_or(&b);let decoded=sprite::decode_classic_spr_with_limits(raw,sprite::SpriteLimits{max_input_bytes:1024*1024,max_frames:255,max_blocks:8192,max_block_references:65536,max_frame_dimension:2048,max_total_pixels:4*1024*1024}).unwrap();assert_eq!(decoded.frames.len(),v.member.frames as usize);pins.insert(v.member.name.clone(),sha(&b));cache.insert(v.member.name.clone(),decoded);}let frame=&cache[&v.member.name].frames[v.catalog.subframe as usize];assert!(frame.width as usize<=cell&&frame.height as usize<=cell);let x0=column*cell+(cell-frame.width as usize)/2;let y0=row*cell+(cell-frame.height as usize)/2;let mut visible=0;for y in 0..frame.height as usize{for x in 0..frame.width as usize{let src=&frame.rgba[(y*frame.width as usize+x)*4..(y*frame.width as usize+x+1)*4];if src[3]==0{continue;}let pos=((y0+y)*width+x0+x)*4;for c in 0..3{rgba[pos+c]=((u32::from(src[c])*u32::from(src[3])+u32::from(rgba[pos+c])*(255-u32::from(src[3]))+127)/255)as u8;}visible+=1;}}cells.push(json!({"source":owner.source,"object":owner.object,"epoch_hex":format!("{:016x}",owner.epoch),"revision":owner.revision,"Class":owner.class,"weapon":owner.weapon,"retainedType":owner.retained_type,"action":v.action,"heading":v.heading,"graphics":v.graphics,"catalog_frame":v.frame,"member":v.member.name,"member_sha256":pins[&v.member.name],"subframe":v.catalog.subframe,"ticks":v.catalog.ticks,"fps":v.fps,"start_ms":v.start_ms,"end_ms":v.end_ms,"elapsed_ms":v.elapsed_ms,"raw_events_hex":v.catalog.events.iter().map(|b|format!("{b:02x}")).collect::<String>(),"source_offset":[frame.x_offset,frame.y_offset],"sample_size":[frame.width,frame.height],"visible_pixels":visible,"world_placement":false}));start=v.end_ms;}}let path=out.join(format!("body-{label}-single-catalog-interval.png"));let mut enc=png::Encoder::new(fs::File::create(&path).unwrap(),width as u32,height as u32);enc.set_color(png::ColorType::Rgba);enc.set_depth(png::BitDepth::Eight);enc.write_header().unwrap().write_image_data(&rgba).unwrap();outputs.push(json!({"kind":label,"path":path,"sha256":sha(&fs::read(&path).unwrap()),"RGBA_sha256":sha(&rgba),"dimensions":[width,height],"cells":cells}));}fs::write(Path::new(env!("CARGO_MANIFEST_DIR")).join("logs/continuation-20261003/r443-cpu-clock-details.json"),serde_json::to_vec_pretty(&json!({"state":"OFFLINE_BODY_WALK_ATTACK_SINGLE_INTERVAL_ACTUAL_SPR_CPU_STUDY","outputs":outputs,"unique_members_decoded":cache.len(),"member_pins":pins,"walk_rows":"historical Type0 weapon3;historical Type0 effective unarmed;historical Type3/Class734 weapon2","attack_rows":"historical Type3/Class734 weapon2 only; Type0 attack1/51 refused because first tick0","columns":"catalog order sampled at exact integer-millisecond frame starts","source_identity":"R439 historical NAB/Class separately observed; not R441/R442 live Class or appearance lease","scope":"centered individual body frames only; events not dispatched; shadow/105/world/depth/loop unqualified","renderer_LOADED":false,"GUI":0})).unwrap()).unwrap();}
